522.     ///
523.     /// # Description
524.     ///
525.     /// Allocates all frames in the given region.
526.     ///
527.     /// # Parameters
528.     ///
529.     /// - `region`: Physical memory region whose frames should be booked.
530.     ///
531.     /// # Returns
532.     ///
533.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
534.     ///
535.     #[verus_verify(external_body)]
536.     #[verus_spec(result =>
537.         requires
538.             old(self).inv(),
539.             region.inv(),
540.         ensures
541.             final(self).inv(),
542.             ({
543.                 let start_frame_number = region@.start / spec_page_size();
544.                 let end_frame_number = (region@.start + region@.size) / spec_page_size();
545.                 let frame_numbers = vstd::set_lib::set_int_range(start_frame_number, end_frame_number);
546.                 let frames = frame_numbers.map(|i: int| i * spec_page_size());
547.                 match result {
548.                     Ok(()) => {
549.                         &&& frames.subset_of(old(self)@.free_frames)
550.                         &&& final(self)@ == FrameAllocView {
551.                             allocated_frames: old(self)@.allocated_frames.union(frames),
552.                             free_frames: old(self)@.free_frames.difference(frames),
553.                             refcounts: old(self)@.refcounts.union_prefer_right(
554.                                 Map::new(|addr: int| frames.contains(addr), |addr: int| 1int)
555.                             ),
556.                         }
557.                     },
558.                     Err(_) => {
559.                         &&& final(self)@ == old(self)@
560.                         &&& !frames.subset_of(old(self)@.free_frames)
561.                     },
562.                 }
563.             }),
564.     )]
565.     fn alloc_range(
566.         &mut self,
567.         region: &TruncatedMemoryRegion<PhysicalAddress>,
568.     ) -> Result<(), Error> {
569.         let start_frame_number: usize = region.start().into_frame_number().into_raw_value();
570.         let end_frame_number: usize = start_frame_number + region.size() / mem::FRAME_SIZE - 1;
571. 
572.         // Check that all frames in the range are covered by the bitmap and free,
573.         // then book them. Uncovered frames indicate a memory layout bug.
574.         //
575.         // The coverage check runs unconditionally — including optimized builds —
576.         // because out-of-bounds indices must be rejected before attempting to set them.
577.         // This loop runs only at boot when booking memory regions, so the overhead is negligible.
578.         for index in start_frame_number..=end_frame_number {
579.             if index >= self.bitmap.number_of_bits() {
580.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
581.                 let reason: &str = "frame index not covered by the bitmap";
582.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
583.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
584.             }
585.             match self.bitmap.test(index) {
586.                 Ok(false) => {},
587.                 Ok(true) => {
588.                     let conflicting_addr: usize = index * mem::FRAME_SIZE;
589.                     let region_start: usize = region.start().into_raw_value();
590.                     let region_end: usize = region_start.saturating_add(region.size());
591.                     let reason: &str = "frame is already allocated";
592.                     error!(
593.                         "{} (frame={:#010x}, region_start={:#010x}, region_end={:#010x})",
594.                         reason, conflicting_addr, region_start, region_end
595.                     );
596.                     return Err(Error::new(ErrorCode::OutOfMemory, reason));
597.                 },
598.                 Err(err) => return Err(err),
599.             }
600.         }
601. 
602.         // Book all frames in the range.
603.         for index in start_frame_number..=end_frame_number {
604.             if let Err(error) = self.bitmap.set(index) {
605.                 error!("{error:?} (region={region:?})");
606.                 return Err(error);
607.             }
608.             debug_assert_eq!(self.refcount[index], 0);
609.             self.refcount[index] = 1;
610.         }
611. 
612.         Ok(())
613.     }
614. }
